// === 1. 实体类 ===
@Data
@TableName("t_user")
public class User {
    @TableId(type = IdType.ASSIGN_ID)  // 雪花算法生成 ID
    private Long id;

    @TableField("user_name")  // 列名映射
    private String userName;

    private Integer age;

    @TableField(fill = FieldFill.INSERT)  // 插入时自动填充
    private LocalDateTime createTime;

    @TableField(fill = FieldFill.INSERT_UPDATE)  // 插入和更新时自动填充
    private LocalDateTime updateTime;

    @Version  // 乐观锁版本号
    private Integer version;

    @TableLogic  // 逻辑删除
    private Integer deleted;
}

// === 2. Mapper ===
@Mapper
public interface UserMapper extends BaseMapper<User> {
    // 自定义多表查询：MP 不自动加逻辑删除条件，需要自己写
    @Select("SELECT u.*, o.order_count FROM t_user u " +
            "LEFT JOIN (SELECT user_id, COUNT(*) cnt FROM t_order GROUP BY user_id) o " +
            "ON u.id = o.user_id WHERE u.deleted = 0")
    List<UserVO> selectUserWithOrderCount();
}

// === 3. Service ===
public interface UserService extends IService<User> {}

@Service
public class UserServiceImpl extends ServiceImpl<UserMapper, User> implements UserService {}

// === 4. 使用 ===
@Service
public class UserBizService {
    @Autowired
    private UserService userService;
    @Autowired
    private UserMapper userMapper;

    public void demo() {
        // LambdaQueryWrapper：类型安全
        LambdaQueryWrapper<User> qw = new LambdaQueryWrapper<>();
        qw.eq(User::getAge, 25)
          .like(User::getUserName, "tom")
          .ge(User::getAge, 18)
          .orderByDesc(User::getCreateTime);
        List<User> users = userMapper.selectList(qw);

        // 链式调用：更简洁
        List<User> chainResult = new LambdaQueryChainWrapper<>(userMapper)
                .eq(User::getAge, 25)
                .like(User::getUserName, "tom")
                .last("LIMIT 10")  // 拼接SQL尾部，慎用——破坏方言兼容性
                .list();

        // 分页查询
        IPage<User> page = new Page<>(2, 10);  // 第2页，每页10条
        IPage<User> result = userMapper.selectPage(page, qw);
        // result.getRecords() → 当前页数据
        // result.getTotal()    → 总记录数（自动COUNT）

        // LambdaUpdateWrapper：更新操作，set 指定更新字段
        LambdaUpdateWrapper<User> uw = new LambdaUpdateWrapper<>();
        uw.eq(User::getId, 1L)
          .set(User::getUserName, "newName")
          .set(User::getAge, null);  // 注意：set 的 null 值会被写入
        userMapper.update(null, uw);

        // updateById 的坑：默认不更新 null 字段
        User u = new User();
        u.setId(1L);
        u.setAge(null);  // 这个 null 不会出现在 UPDATE 语句中
        userService.updateById(u);  // 实际执行: UPDATE t_user WHERE id=1（没更新任何列）
    }
}

// === 5. 自动填充处理器 ===
@Component
public class MyMetaObjectHandler implements MetaObjectHandler {
    @Override
    public void insertFill(MetaObject metaObject) {
        this.strictInsertFill(metaObject, "createTime", LocalDateTime::now, LocalDateTime.class);
        this.strictInsertFill(metaObject, "updateTime", LocalDateTime::now, LocalDateTime.class);
    }

    @Override
    public void updateFill(MetaObject metaObject) {
        this.strictUpdateFill(metaObject, "updateTime", LocalDateTime::now, LocalDateTime.class);
    }
}
